examples.source:
---
const tabs = [{ value: 'profile', label: 'Profile' }, { value: 'security', label: 'Security' }];
---
<Tabs id="account-tabs" aria-label="Account" value="profile" tabs={tabs}>
  <p slot="profile">Profile settings</p>
  <p slot="security">Security settings</p>
</Tabs>
<p>Selected tab: <output id="account-selected">profile</output></p>
<script>
  import { TABS_CHANGE_EVENT, type TabsChangeEvent } from '@claymo/core/behavior/tabs';
  const selected = document.getElementById('account-selected')!;
  document.getElementById('account-tabs')!.addEventListener(TABS_CHANGE_EVENT, (event) => {
    selected.textContent = String((event as TabsChangeEvent).detail.value);
  });
</script>

---
const dialogId = 'account-help';
---
<Button commandfor={dialogId} command="show-modal">Open help</Button>
<Dialog id={dialogId} title="Account help" dismissible>
  <p>Choose Close, the X, or press Escape to dismiss this dialog.</p>
  <Button slot="actions" variant="text" commandfor={dialogId} command="close">Close</Button>
</Dialog>
<script>
  import { DIALOG_REQUEST_CLOSE_EVENT, type DialogRequestCloseEvent } from '@claymo/core/behavior/dialog';
  document.getElementById('account-help')!.addEventListener(DIALOG_REQUEST_CLOSE_EVENT, (event) => {
    if ((event as DialogRequestCloseEvent).detail.reason === 'backdropClick') event.preventDefault();
  });
</script>

---
const dialogId = "team-meeting";
---

<Button commandfor={dialogId} command="show-modal">
  Open event
</Button>
<Dialog id={dialogId} title="Team meeting" dismissible>
  <p data-view>Weekly sync with the design team.</p>
  <div data-edit hidden>
    <TextField label="Description" multiline rows={3} fullWidth />
  </div>
  <Button slot="actions" variant="outlined" data-start-edit>
    Edit
  </Button>
  <Button slot="actions" variant="text" data-cancel hidden>
    Cancel
  </Button>
  <Button slot="actions" data-save hidden>
    Save
  </Button>
</Dialog>

<script>
  import { DIALOG_REQUEST_CLOSE_EVENT } from "@claymo/core/behavior/dialog";

  const dialog = document.getElementById("team-meeting") as HTMLDialogElement;
  const view = dialog.querySelector<HTMLElement>("[data-view]")!;
  const edit = dialog.querySelector<HTMLElement>("[data-edit]")!;
  const field = edit.querySelector("textarea")!;
  const start = dialog.querySelector<HTMLButtonElement>("[data-start-edit]")!;
  const cancel = dialog.querySelector<HTMLButtonElement>("[data-cancel]")!;
  const save = dialog.querySelector<HTMLButtonElement>("[data-save]")!;
  const dirty = () => !edit.hidden && field.value !== view.textContent;

  function setEditing(editing: boolean) {
    for (const element of [view, start]) element.hidden = editing;
    for (const element of [edit, cancel, save]) element.hidden = !editing;
    if (editing) {
      field.value = view.textContent ?? "";
      field.focus();
    }
  }
  start.addEventListener("click", () => setEditing(true));
  cancel.addEventListener("click", () => setEditing(false));
  save.addEventListener("click", () => {
    view.textContent = field.value;
    setEditing(false);
  });
  // Escape, backdrop clicks and the X ask first when there are unsaved edits.
  dialog.addEventListener(DIALOG_REQUEST_CLOSE_EVENT, (event) => {
    if (dirty() && !confirm("Discard unsaved changes?")) event.preventDefault();
  });
  dialog.addEventListener("close", () => setEditing(false));
</script>
